export const DISEASE_LIBRARY = [{"id":"m_ich","type":"marine","group":"fish","ar":"النقاط البيضاء البحرية (Cryptocaryon)","en":"Marine Ich (Cryptocaryon)","symAr":"نقاط بيضاء، حك الجسم، تنفس أسرع من المعتاد.","symEn":"White spots, flashing, increased breathing.","txAr":"اعزل الأسماك المصابة، ثبّت جودة الماء والأكسجة، واستخدم علاجاً معتمداً في حوض علاجي. تجنّب النحاس داخل حوض المرجان واللافقاريات.","txEn":"Quarantine affected fish, stabilize water and aeration, and use a validated hospital-tank treatment. Do not use copper in a reef/invertebrate display.","urgent":false},{"id":"m_velvet","type":"marine","group":"fish","ar":"الفيلفت البحري (Amyloodinium)","en":"Marine Velvet (Amyloodinium)","symAr":"غبار ناعم ذهبي/رمادي، تنفس شديد، اختباء من الضوء وتدهور سريع.","symEn":"Fine gold/gray dusting, severe breathing, light avoidance, rapid decline.","txAr":"حالة عاجلة: اعزل سريعاً، ارفع الأكسجة، وابدأ علاجاً مناسباً في حوض علاجي بعد تأكيد الاشتباه.","txEn":"Urgent: isolate rapidly, maximize aeration, and begin an appropriate hospital-tank treatment after confirming suspicion.","urgent":true},{"id":"m_brook","type":"marine","group":"fish","ar":"بروكلينيلا","en":"Brooklynella","symAr":"مخاط كثيف، تنفس سريع، خمول وتقشر جلدي خاصة لدى المهرج.","symEn":"Heavy mucus, rapid breathing, lethargy and skin sloughing, often in clownfish.","txAr":"اعزل فوراً وحسّن الأكسجة ونوعية الماء، ثم استخدم بروتوكول علاج مناسب في حوض علاجي.","txEn":"Isolate immediately, improve aeration and water quality, then use an appropriate hospital-tank protocol.","urgent":true},{"id":"m_uronema","type":"marine","group":"fish","ar":"يورونيما","en":"Uronema","symAr":"بقع حمراء/تقرحات، تنفس سريع وتدهور قد يكون سريعاً.","symEn":"Red sores/ulcers, rapid breathing and potentially rapid decline.","txAr":"اعزل الحالة، راجع جودة الماء، وتجنّب نقل ماء الحجر إلى الحوض الرئيسي. العلاج يعتمد على التشخيص المؤكد.","txEn":"Quarantine, review water quality, and avoid cross-contamination. Treatment depends on confirmed diagnosis.","urgent":true},{"id":"m_flukes","type":"marine","group":"fish","ar":"ديدان الخياشيم/الجلد","en":"Gill or Skin Flukes","symAr":"حك متكرر، مخاط زائد، تنفس سريع أو عين معتمة.","symEn":"Persistent flashing, excess mucus, rapid breathing or cloudy eye.","txAr":"اعزل وافحص العلامات بعناية، وحسّن الأكسجة. استخدم علاجاً مخصصاً للطفيليات في حوض علاجي حسب إرشادات المنتج.","txEn":"Quarantine, assess carefully, improve aeration, and use an appropriate antiparasitic hospital treatment per label.","urgent":false},{"id":"m_bacterial","type":"marine","group":"fish","ar":"عدوى بكتيرية / تعفن الزعانف","en":"Bacterial / Fin Infection","symAr":"احمرار، جروح، تآكل الزعانف أو تقرحات.","symEn":"Redness, wounds, frayed fins or ulcers.","txAr":"حسّن جودة الماء وخفّض الضغط، واعزل الحالات المتقدمة. العلاج الدوائي يختار حسب الاشتباه وشدة الإصابة.","txEn":"Improve water quality and reduce stress; quarantine advanced cases. Medication choice depends on the suspected cause and severity.","urgent":false},{"id":"m_lympho","type":"marine","group":"fish","ar":"ليمفوسيستس","en":"Lymphocystis","symAr":"نتوءات بيضاء/قرنبيطية على الزعانف أو الجلد مع بقاء السمكة مستقرة غالباً.","symEn":"White cauliflower-like nodules on fins or skin, often with otherwise stable behavior.","txAr":"ركّز على جودة الماء والتغذية وتقليل الضغط واعزل إذا كان هناك تنمر أو إصابات ثانوية.","txEn":"Focus on water quality, nutrition and stress reduction; isolate if bullying or secondary injury occurs.","urgent":false},{"id":"m_popeye","type":"marine","group":"fish","ar":"جحوظ العين","en":"Popeye / Exophthalmia","symAr":"انتفاخ عين واحدة أو كلتيهما، أحياناً مع عتامة.","symEn":"One or both eyes protrude, sometimes cloudy.","txAr":"تحقق من الإصابات وجودة الماء. الحالات الثنائية أو المصحوبة بأعراض عامة تحتاج تقييماً أوسع وعزلاً عند الحاجة.","txEn":"Check for trauma and water quality. Bilateral or systemic cases need broader assessment and possible quarantine.","urgent":false},{"id":"m_hlle","type":"marine","group":"fish","ar":"تآكل الرأس والخط الجانبي","en":"Head & Lateral Line Erosion","symAr":"تآكل أو حفر حول الرأس والخط الجانبي.","symEn":"Erosions or pits around the head and lateral line.","txAr":"راجع التغذية، جودة الماء، الكربون النشط والغبار/الضغط المزمن. عالج العوامل البيئية أولاً.","txEn":"Review nutrition, water quality, activated-carbon dust and chronic stress; correct environmental contributors first.","urgent":false},{"id":"m_internal","type":"marine","group":"fish","ar":"طفيليات داخلية / هزال","en":"Internal Parasites / Wasting","symAr":"نقص وزن رغم الأكل، براز غير طبيعي أو فقد شهية.","symEn":"Weight loss despite feeding, abnormal feces or poor appetite.","txAr":"اعزل عند الإمكان، راقب البراز والتغذية، واستخدم علاجاً مخصصاً فقط بعد ترجيح السبب.","txEn":"Quarantine if practical, monitor feces and feeding, and use targeted treatment only after the cause is reasonably suspected.","urgent":false},{"id":"f_ich","type":"freshwater","group":"fish","ar":"النقاط البيضاء","en":"Freshwater Ich","symAr":"نقاط بيضاء، حك الجسم وخمول.","symEn":"White spots, flashing and lethargy.","txAr":"ثبّت الحرارة والأكسجة وجودة الماء واستخدم علاجاً مناسباً للمياه العذبة حسب الملصق مع مراعاة حساسية الأنواع.","txEn":"Stabilize temperature, aeration and water quality; use an appropriate freshwater treatment per label and species sensitivity.","urgent":false},{"id":"f_velvet","type":"freshwater","group":"fish","ar":"الفيلفت","en":"Freshwater Velvet","symAr":"غبار ذهبي/صدئي، حك، انكماش الزعانف وتنفس متعب.","symEn":"Gold/rust dusting, flashing, clamped fins and labored breathing.","txAr":"اعزل إن أمكن، حسّن الأكسجة وابدأ علاجاً مناسباً بعد تأكيد الاشتباه.","txEn":"Quarantine if possible, improve aeration and start an appropriate treatment after confirming suspicion.","urgent":true},{"id":"f_finrot","type":"freshwater","group":"fish","ar":"تعفن الزعانف","en":"Fin Rot","symAr":"تآكل أو تغير لون حواف الزعانف.","symEn":"Frayed or discolored fin edges.","txAr":"حسّن جودة الماء وقلّل الضغط، ثم عالج العدوى إذا استمر التدهور أو ظهرت تقرحات.","txEn":"Improve water quality and reduce stress; treat infection if deterioration continues or ulcers appear.","urgent":false},{"id":"f_columnaris","type":"freshwater","group":"fish","ar":"كولومناريس","en":"Columnaris","symAr":"بقع شاحبة/بيضاء، تآكل حول الفم أو الظهر وتدهور سريع أحياناً.","symEn":"Pale/white patches, mouth or saddle lesions, sometimes rapid decline.","txAr":"اعزل الحالات المشتبه بها، حسّن الأكسجة ونوعية الماء، واطلب علاجاً موجهاً سريعاً عند التدهور.","txEn":"Isolate suspected cases, improve aeration and water quality, and seek prompt targeted treatment if declining.","urgent":true},{"id":"f_fungal","type":"freshwater","group":"fish","ar":"عدوى فطرية","en":"Fungal Infection","symAr":"نمو قطني على الجلد أو الجروح.","symEn":"Cotton-like growth on skin or wounds.","txAr":"اعزل وفحص وجود جرح أو مشكلة ماء، وميّزها عن العدوى البكتيرية قبل العلاج.","txEn":"Quarantine, look for underlying injury or water-quality issues, and distinguish it from bacterial disease before treatment.","urgent":false},{"id":"f_dropsy","type":"freshwater","group":"fish","ar":"الاستسقاء / انتفاخ مع بروز القشور","en":"Dropsy / Pineconing","symAr":"انتفاخ الجسم وبروز القشور وخمول.","symEn":"Body swelling, raised scales and lethargy.","txAr":"حالة خطرة متعددة الأسباب: اعزل، راجع الماء، واطلب تقييماً سريعاً قبل العلاج.","txEn":"Serious sign with multiple possible causes: quarantine, review water quality and seek prompt assessment before treatment.","urgent":true},{"id":"f_popeye","type":"freshwater","group":"fish","ar":"جحوظ العين","en":"Popeye","symAr":"انتفاخ عين أو كلتيهما.","symEn":"One or both eyes protrude.","txAr":"تحقق من الإصابات والأمونيا/النتريت وجودة الماء واعزل إذا كانت الحالة جهازية.","txEn":"Check for trauma, ammonia/nitrite and water quality; quarantine if systemic signs are present.","urgent":false},{"id":"f_swim","type":"freshwater","group":"fish","ar":"اضطراب الطفو","en":"Buoyancy / Swim Bladder Problem","symAr":"صعوبة في الاتزان أو الصعود/الهبوط.","symEn":"Difficulty maintaining position or buoyancy.","txAr":"تحقق من الإمساك، الإصابات، جودة الماء والعدوى المحتملة. لا تفترض سبباً واحداً قبل الفحص.","txEn":"Check constipation, injury, water quality and possible infection; do not assume one cause without assessment.","urgent":false},{"id":"f_flukes","type":"freshwater","group":"fish","ar":"ديدان الخياشيم/الجلد","en":"Gill or Skin Flukes","symAr":"حك متكرر، تنفس سريع ومخاط زائد.","symEn":"Persistent flashing, rapid breathing and excess mucus.","txAr":"اعزل وحسّن الأكسجة واستخدم علاجاً مضاداً للطفيليات مناسباً للمياه العذبة وفق الملصق.","txEn":"Quarantine, improve aeration and use an appropriate freshwater antiparasitic treatment per label.","urgent":false},{"id":"f_hex","type":"freshwater","group":"fish","ar":"هيكساميتا / ثقب الرأس","en":"Hexamita / Hole-in-the-Head","symAr":"براز أبيض، هزال، فقد شهية أو حفر بالرأس في بعض السيكليد.","symEn":"White feces, wasting, poor appetite or head pits in some cichlids.","txAr":"راجع التغذية والماء والعوامل المزمنة، واعزل للعلاج الموجّه إذا تأكد الاشتباه.","txEn":"Review nutrition, water quality and chronic stressors; quarantine for targeted treatment when reasonably confirmed.","urgent":false},{"id":"f_anchor","type":"freshwater","group":"fish","ar":"دودة المرساة","en":"Anchor Worm","symAr":"طفيلي خيطي بارز من الجلد مع احمرار موضعي.","symEn":"Thread-like parasite protruding from skin with local inflammation.","txAr":"اعزل عند الإمكان وعالج الطفيلي ودورة حياته في النظام وفق منتج مناسب للمياه العذبة.","txEn":"Quarantine when possible and treat both the parasite and its life cycle with an appropriate freshwater product.","urgent":false},{"id":"m_molt","type":"marine","group":"crustacean","ar":"فشل الانسلاخ","en":"Molting Failure","symAr":"تعثر في الخروج من الهيكل القديم، خمول أو موت بعد محاولة الانسلاخ.","symEn":"Difficulty leaving the old exoskeleton, lethargy or death around molt.","txAr":"ثبّت الملوحة/المعادن المناسبة للنوع، تجنب التغيرات السريعة، وافحص جودة الماء والمعادن الأساسية.","txEn":"Keep salinity/minerals appropriate for the species, avoid rapid changes, and review water quality and key minerals.","urgent":false},{"id":"m_shell","type":"marine","group":"crustacean","ar":"تقرحات أو مرض القشرة","en":"Shell Lesions / Shell Disease","symAr":"بقع داكنة أو تآكل أو حفر على القشرة.","symEn":"Dark spots, erosion or pits on the shell.","txAr":"حسّن جودة الماء والنظافة وقلل الجروح والضغط. اعزل إذا كان هناك تدهور أو عدوى ثانوية.","txEn":"Improve water quality and hygiene, reduce injury/stress, and isolate if lesions progress or secondary infection develops.","urgent":false},{"id":"m_osmotic","type":"marine","group":"crustacean","ar":"صدمة أسموزية / تغير مفاجئ بالماء","en":"Osmotic Shock","symAr":"خمول أو فقد اتزان بعد نقل أو تغيير ماء كبير.","symEn":"Lethargy or loss of coordination after transfer or major water change.","txAr":"ثبّت القيم وتجنب تصحيحات سريعة إضافية. راجع طريقة التأقلم والملوحة/TDS حسب النوع.","txEn":"Stabilize conditions and avoid further rapid corrections. Review acclimation and salinity/TDS as appropriate.","urgent":true},{"id":"m_toxicity","type":"marine","group":"crustacean","ar":"تسمم بالنحاس أو المعادن","en":"Copper / Heavy-Metal Toxicity","symAr":"خمول مفاجئ، فقد اتزان أو نفوق عدة لافقاريات معاً.","symEn":"Sudden lethargy, loss of coordination or multiple invertebrate deaths.","txAr":"أوقف المصدر المشتبه، اختبر الماء إن أمكن، استخدم ماءً آمناً ووسائط إزالة مناسبة، وارفَع الأكسجة.","txEn":"Stop the suspected source, test if possible, use safe replacement water and appropriate removal media, and increase aeration.","urgent":true},{"id":"f_molt","type":"freshwater","group":"crustacean","ar":"فشل الانسلاخ","en":"Molting Failure","symAr":"تعثر في الخروج من الهيكل القديم، خمول أو موت بعد محاولة الانسلاخ.","symEn":"Difficulty leaving the old exoskeleton, lethargy or death around molt.","txAr":"ثبّت الملوحة/المعادن المناسبة للنوع، تجنب التغيرات السريعة، وافحص جودة الماء والمعادن الأساسية.","txEn":"Keep salinity/minerals appropriate for the species, avoid rapid changes, and review water quality and key minerals.","urgent":false},{"id":"f_shell","type":"freshwater","group":"crustacean","ar":"تقرحات أو مرض القشرة","en":"Shell Lesions / Shell Disease","symAr":"بقع داكنة أو تآكل أو حفر على القشرة.","symEn":"Dark spots, erosion or pits on the shell.","txAr":"حسّن جودة الماء والنظافة وقلل الجروح والضغط. اعزل إذا كان هناك تدهور أو عدوى ثانوية.","txEn":"Improve water quality and hygiene, reduce injury/stress, and isolate if lesions progress or secondary infection develops.","urgent":false},{"id":"f_osmotic","type":"freshwater","group":"crustacean","ar":"صدمة أسموزية / تغير مفاجئ بالماء","en":"Osmotic Shock","symAr":"خمول أو فقد اتزان بعد نقل أو تغيير ماء كبير.","symEn":"Lethargy or loss of coordination after transfer or major water change.","txAr":"ثبّت القيم وتجنب تصحيحات سريعة إضافية. راجع طريقة التأقلم والملوحة/TDS حسب النوع.","txEn":"Stabilize conditions and avoid further rapid corrections. Review acclimation and salinity/TDS as appropriate.","urgent":true},{"id":"f_toxicity","type":"freshwater","group":"crustacean","ar":"تسمم بالنحاس أو المعادن","en":"Copper / Heavy-Metal Toxicity","symAr":"خمول مفاجئ، فقد اتزان أو نفوق عدة لافقاريات معاً.","symEn":"Sudden lethargy, loss of coordination or multiple invertebrate deaths.","txAr":"أوقف المصدر المشتبه، اختبر الماء إن أمكن، استخدم ماءً آمناً ووسائط إزالة مناسبة، وارفَع الأكسجة.","txEn":"Stop the suspected source, test if possible, use safe replacement water and appropriate removal media, and increase aeration.","urgent":true},{"id":"c_brownjelly","type":"marine","group":"coral","ar":"البراون جيلي","en":"Brown Jelly Syndrome","symAr":"نسيج بني هلامي سريع الانتشار مع تراجع نسيج خاصة في بعض LPS.","symEn":"Rapid brown jelly-like tissue loss, often on some LPS corals.","txAr":"اعزل القطعة المتأثرة إن أمكن، حسّن التدفق والنظافة وتجنب نشر الأنسجة المتحللة. الحالات المتقدمة تحتاج تدخلاً متخصصاً.","txEn":"Isolate the affected coral if practical, improve flow and hygiene, and avoid spreading decaying tissue. Advanced cases need expert intervention.","urgent":true},{"id":"c_bleach","type":"marine","group":"coral","ar":"ابيضاض المرجان","en":"Coral Bleaching","symAr":"فقد لون واضح مع بقاء النسيج أو انكماشه.","symEn":"Marked color loss with tissue still present or contracted.","txAr":"راجع الحرارة والإضاءة والملوحة والتغيرات الأخيرة. صحح السبب تدريجياً ولا تجرِ تغييرات متعددة دفعة واحدة.","txEn":"Review temperature, light, salinity and recent changes. Correct the cause gradually and avoid multiple simultaneous changes.","urgent":false},{"id":"c_tissue","type":"marine","group":"coral","ar":"تراجع الأنسجة","en":"Tissue Recession","symAr":"انحسار النسيج وكشف الهيكل تدريجياً أو سريعاً.","symEn":"Tissue retracts and exposes skeleton, slowly or rapidly.","txAr":"راجع ثبات KH والحرارة والملوحة والتدفق والآفات. اعزل القطعة إذا كان التراجع سريعاً أو معدياً.","txEn":"Review KH stability, temperature, salinity, flow and pests. Isolate if recession is rapid or potentially contagious.","urgent":true},{"id":"c_rtn","type":"marine","group":"coral","ar":"RTN / STN في SPS","en":"RTN / STN in SPS","symAr":"فقد سريع أو بطيء للأنسجة من الهيكل.","symEn":"Rapid or slow tissue loss from the skeleton.","txAr":"ثبّت الكيمياء والحرارة، افحص الآفات والتدفق، واعزل/قص الأجزاء السليمة إذا لزم وفق خبرة مناسبة.","txEn":"Stabilize chemistry and temperature, inspect for pests/flow issues, and isolate or frag healthy tissue when appropriate and experienced.","urgent":true},{"id":"c_flatworms","type":"marine","group":"coral","ar":"ديدان مسطحة / آفات المرجان","en":"Coral Flatworms / Pests","symAr":"بقع عض، انكماش، فقد لون أو مشاهدة آفات/بيض.","symEn":"Bite marks, contraction, color loss, or visible pests/eggs.","txAr":"اعزل وافحص بصرياً واستخدم غمساً مناسباً خارج الحوض عند توافقه مع نوع المرجان، مع تكرار الفحص لدورة الآفة.","txEn":"Quarantine and inspect; use an appropriate coral dip outside the display when suitable for the coral, and repeat inspections for the pest life cycle.","urgent":false},{"id":"c_zoapox","type":"marine","group":"coral","ar":"زوَا بوكس","en":"Zoanthid Pox","symAr":"بثور/نقاط فاتحة على بوليبات الزوانثيد مع انغلاقها.","symEn":"Pale pustules/spots on zoanthid polyps with prolonged closure.","txAr":"اعزل القطعة، حسّن الظروف وقلل الانتشار بين المستعمرات. استخدم معالجة متخصصة فقط بعد تأكيد الاشتباه.","txEn":"Isolate the colony, improve conditions and prevent spread. Use specialized treatment only after reasonable confirmation.","urgent":false},{"id":"p_n","type":"freshwater","group":"plant","ar":"نقص النيتروجين","en":"Nitrogen Deficiency","symAr":"اصفرار الأوراق القديمة وضعف النمو.","symEn":"Older leaves yellow and growth slows.","txAr":"قِس النترات أولاً، ووازن التسميد تدريجياً مع تجنب الرفع السريع.","txEn":"Measure nitrate first, then adjust fertilization gradually without rapid increases.","urgent":false},{"id":"p_k","type":"freshwater","group":"plant","ar":"نقص البوتاسيوم","en":"Potassium Deficiency","symAr":"ثقوب صغيرة أو حواف ميتة في الأوراق القديمة.","symEn":"Pinholes or necrotic edges on older leaves.","txAr":"راجع برنامج التسميد والتوازن العام، وأضف البوتاسيوم تدريجياً إذا كان النقص مرجحاً.","txEn":"Review the fertilizer program and overall balance; increase potassium gradually if deficiency is likely.","urgent":false},{"id":"p_fe","type":"freshwater","group":"plant","ar":"نقص الحديد","en":"Iron Deficiency","symAr":"اصفرار الأوراق الجديدة مع بقاء العروق أو ضعف اللون الأحمر.","symEn":"New leaves become pale/yellow, sometimes with greener veins or weak red coloration.","txAr":"راجع الحديد والعناصر الصغرى والإضاءة وpH، وعدل الجرعات تدريجياً.","txEn":"Review iron, trace nutrients, lighting and pH, and adjust dosing gradually.","urgent":false},{"id":"p_melt","type":"freshwater","group":"plant","ar":"ذوبان الأوراق","en":"Plant Melt","symAr":"شفافية أو تحلل أوراق بعد الزراعة أو تغير الظروف.","symEn":"Leaves become transparent or decay after planting or a major change.","txAr":"أزل الأنسجة المتحللة، ثبّت الظروف، وامنح الجذور/النمو الجديد وقتاً قبل تغيير عوامل متعددة.","txEn":"Remove decaying tissue, stabilize conditions and allow time for new growth before changing multiple variables.","urgent":false},{"id":"p_root","type":"freshwater","group":"plant","ar":"تعفن الجذور","en":"Root Rot","symAr":"جذور داكنة/طرية، رائحة أو توقف نمو نباتات الجذور.","symEn":"Dark soft roots, odor or stalled growth in root feeders.","txAr":"راجع سماكة ونظافة الركيزة وتراكم المواد العضوية، وأزل الأجزاء المتعفنة وحسّن الظروف.","txEn":"Review substrate condition and organic buildup, remove rotten tissue and improve conditions.","urgent":false},{"id":"p_algae","type":"freshwater","group":"plant","ar":"تغطية الطحالب للنبات","en":"Algae Overgrowth on Plants","symAr":"طحالب على الأوراق مع ضعف وصول الضوء أو تباطؤ النمو.","symEn":"Algae coats leaves, reducing light and growth.","txAr":"وازن الإضاءة والمغذيات وCO2 والصيانة، وتجنب خفض عنصر واحد بعنف.","txEn":"Balance light, nutrients, CO2 and maintenance; avoid aggressively zeroing a single nutrient.","urgent":false},{"id":"p_stunt","type":"freshwater","group":"plant","ar":"تقزم أو تشوه النمو الجديد","en":"Stunted / Twisted New Growth","symAr":"أوراق جديدة صغيرة أو ملتوية ونمو متوقف.","symEn":"New leaves are small/twisted and growth stalls.","txAr":"راجع CO2 والاستقرار والعناصر الصغرى والكالسيوم/المغنيسيوم حسب الماء، وعدل عاملاً واحداً كل مرة.","txEn":"Review CO2 stability, trace nutrients and Ca/Mg as relevant; change one factor at a time.","urgent":false}] as const;

